import React, { } from 'react'
import { View, Text } from 'react-native'

import { styles } from './styles'

export function Cards({ listItemProps, position }: any) {


    return (
        <View>
            <Text style={[styles.listText, { backgroundColor: '#fff', color: '#121212' }]}>
                {(`0000${listItemProps.data.lineCards + position}`).slice(-4)}
            </Text>
            <Text style={{ fontSize: 20, position: 'absolute', backgroundColor: 'rgba(0,0,0,0.8)', padding: 5, color: '#fff' }}>{props.db?.['Fabio Moraes'][0]['price']}</Text>
        </View>
    )
}
